"""Local, pencil-friendly abstract workspace. Browser storage stays on this device."""
import json
import streamlit as st
from services.papers import safe_url


HTML = r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
:root{font:14px/1.4 system-ui,sans-serif;--bg:#0e1f2a;--pane:#142d3a;--line:#315663;--ink:#edf7f7;--muted:#a8c8ce;--teal:#5cc9c9;--note:#174453;--paper:#eef8f8;--paperInk:#183b45}
body.light{--bg:#f1f9fa;--pane:#fff;--line:#bfdee2;--ink:#183b45;--muted:#567580;--teal:#197f8a;--note:#def5f4;--paper:#fff;--paperInk:#183b45}
*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--bg)}button,select,input,textarea{font:inherit}button,select{border:1px solid var(--line);border-radius:9px;background:var(--pane);color:var(--ink);padding:7px 9px;cursor:pointer}button:hover{border-color:var(--teal)}button.active{background:var(--teal);color:#08242d}button:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--teal)}
.layout{display:grid;grid-template-columns:156px minmax(220px,1fr) minmax(250px,1fr);height:590px;gap:8px;padding:6px}.pane{min-width:0;background:var(--pane);border:1px solid var(--line);border-radius:14px;overflow:hidden;display:flex;flex-direction:column}.head{padding:10px;border-bottom:1px solid var(--line);display:flex;gap:6px;align-items:center;flex-wrap:wrap}.head strong{font-size:13px}.small{font-size:11px;color:var(--muted)}.docs{overflow:auto;padding:8px}.folder{margin:10px 0 4px;font-size:11px;font-weight:700;color:var(--teal);text-transform:uppercase}.doc{display:block;width:100%;text-align:left;margin:4px 0;padding:8px 7px;line-height:1.2}.doc.active{border-color:var(--teal);background:var(--note);color:var(--ink)}.move{width:100%;font-size:11px;margin:2px 0 7px;padding:3px}.document-scroll{position:relative;overflow:auto;flex:1;background:var(--paper);color:var(--paperInk)}.document-surface{position:relative;min-height:100%;padding:20px 23px 50px}.paper-title{font-size:17px;font-weight:700;margin:0 0 12px}.paper-text{white-space:pre-wrap;line-height:1.72;font-size:15px}.document-ink{position:absolute;inset:0;pointer-events:none;touch-action:none}.document-ink.drawing{pointer-events:auto;cursor:crosshair}.source{font-size:11px;color:var(--teal);text-decoration:none}.source:hover{text-decoration:underline}.board{position:relative;flex:1;overflow:hidden;background-image:radial-gradient(var(--line) 0.7px,transparent 0.7px);background-size:18px 18px}.board-ink,.links{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.board-ink.drawing{pointer-events:auto;cursor:crosshair}.note{position:absolute;z-index:3;width:160px;min-height:118px;border:1px solid var(--teal);border-radius:12px;background:var(--note);box-shadow:0 8px 18px #06162030;overflow:hidden}.note.selected{outline:2px solid var(--teal)}.note-handle{cursor:grab;background:#31818b33;padding:5px 8px;font-weight:700;font-size:11px;touch-action:none}.note textarea{display:block;width:100%;height:82px;resize:vertical;border:0;outline:0;background:transparent;color:var(--ink);padding:8px;font-size:12px}.note textarea::placeholder{color:var(--muted)}.status{padding:5px 10px;border-top:1px solid var(--line);font-size:11px;color:var(--muted)}
@media(max-width:650px){.layout{grid-template-columns:112px minmax(180px,1fr);grid-template-rows:290px 290px;height:590px}.docs-pane{grid-row:1 / 3}.board-pane{grid-column:2}.head{padding:6px}.head button{padding:5px;font-size:11px}}
</style></head><body class="__THEME__">
<div class="layout">
 <section class="pane docs-pane"><div class="head"><strong>Documents</strong><button id="add-folder" title="Create a folder">+ Folder</button></div><div class="docs" id="docs"></div></section>
 <section class="pane"><div class="head"><strong>Read</strong><button id="doc-pen" title="Draw over the abstract with a pen or finger">✎ Pen</button><button id="doc-clear" title="Clear document ink">Clear ink</button></div><div class="document-scroll" id="document-scroll"><div class="document-surface" id="document-surface"><div class="paper-title" id="paper-title"></div><div class="small" id="paper-label"></div><p class="paper-text" id="paper-text"></p><a class="source" id="source" target="_blank" rel="noopener noreferrer">Open original source ↗</a><canvas class="document-ink" id="document-ink"></canvas></div></div></section>
 <section class="pane board-pane"><div class="head"><strong>Linked notes</strong><button id="add-note">+ Note</button><button id="link-notes" title="Tap two cards to connect them">Link</button><button id="board-pen" title="Draw on the board with a pen or finger">✎ Pen</button><button id="board-clear" title="Clear board ink">Clear ink</button><button id="export-notes" title="Download note text and links as Markdown; pen strokes stay in this browser">Export</button></div><div class="board" id="board"><svg class="links" id="links"></svg><canvas class="board-ink" id="board-ink"></canvas></div><div class="status" id="status">Notes and ink are saved in this browser.</div></section>
</div><script id="paper-data" type="application/json">__PAPERS__</script><script>
const papers=JSON.parse(document.getElementById('paper-data').textContent);
let current=papers[0]?.id, folders=load('rb_folders_v1',['Reading tray']), assignment=load('rb_folders_for_papers_v1',{}), linkFirst=null, linking=false, docPen=false,boardPen=false;
const $=id=>document.getElementById(id), byId=id=>papers.find(p=>p.id===id), key=kind=>'rb_workspace_v1_'+kind+'_'+current;
function load(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}}
function save(k,value){try{localStorage.setItem(k,JSON.stringify(value))}catch{$('status').textContent='Browser storage is full; notes may not persist.'}}
function state(){return load(key('notes'),{cards:[],links:[],docInk:[],boardInk:[]})}
function setState(value){save(key('notes'),value)}
function renderDocs(){const root=$('docs');root.replaceChildren();for(const folder of folders){const h=document.createElement('div');h.className='folder';h.textContent=folder;root.append(h);for(const paper of papers.filter(p=>(assignment[p.id]||'Reading tray')===folder)){const b=document.createElement('button');b.className='doc'+(paper.id===current?' active':'');b.textContent=paper.title;b.title=paper.title;b.onclick=()=>{current=paper.id;renderAll()};root.append(b);const move=document.createElement('select');move.className='move';move.title='Move paper to folder';for(const name of folders){const o=document.createElement('option');o.value=o.textContent=name;move.append(o)}move.value=folder;move.onchange=()=>{assignment[paper.id]=move.value;save('rb_folders_for_papers_v1',assignment);renderDocs()};root.append(move)}}}
function renderPaper(){const p=byId(current);$('paper-title').textContent=p.title;$('paper-label').textContent=p.kind==='Background article'?'Wikipedia contributors · CC BY-SA 4.0':('Retrieved abstract · '+(p.date||'date unknown'));$('paper-text').textContent=p.abstract||'No preview text is available in this source record. Open the original source.';const source=$('source');source.href=p.url||'#';source.hidden=!p.url;requestAnimationFrame(()=>resizeCanvas($('document-ink'),$('document-surface'),state().docInk))}
function resizeCanvas(canvas,host,strokes){const w=host.clientWidth,h=host.clientHeight;canvas.width=Math.max(w,1);canvas.height=Math.max(h,1);canvas.style.width=w+'px';canvas.style.height=h+'px';drawStrokes(canvas,strokes)}
function drawStrokes(canvas,strokes){const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);c.strokeStyle='#e87761';c.lineWidth=2.3;c.lineCap='round';c.lineJoin='round';for(const points of strokes){c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x*canvas.width,y*canvas.height):c.moveTo(x*canvas.width,y*canvas.height));c.stroke()}}
function ink(canvas,kind){let points=null;canvas.addEventListener('pointerdown',e=>{if(!canvas.classList.contains('drawing'))return;e.preventDefault();canvas.setPointerCapture(e.pointerId);points=[];point(e)});canvas.addEventListener('pointermove',e=>{if(points){point(e);const s=state();drawStrokes(canvas,[...s[kind],points])}});canvas.addEventListener('pointerup',()=>{if(points?.length){const s=state();s[kind].push(points);setState(s)}points=null});function point(e){const r=canvas.getBoundingClientRect();points.push([(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height])}}
function drawLinks(s){const svg=$('links');svg.replaceChildren();const board=$('board');for(const [a,b] of s.links){const A=s.cards.find(c=>c.id===a),B=s.cards.find(c=>c.id===b);if(!A||!B)continue;const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',A.x+80);line.setAttribute('y1',A.y+58);line.setAttribute('x2',B.x+80);line.setAttribute('y2',B.y+58);line.setAttribute('stroke','#5cc9c9');line.setAttribute('stroke-width','2');svg.append(line)}svg.setAttribute('viewBox',`0 0 ${board.clientWidth} ${board.clientHeight}`)}
function renderBoard(){const s=state(),board=$('board');board.querySelectorAll('.note').forEach(n=>n.remove());for(const card of s.cards){const el=document.createElement('div');el.className='note';el.style.left=card.x+'px';el.style.top=card.y+'px';el.dataset.id=card.id;const handle=document.createElement('div');handle.className='note-handle';handle.textContent='⋮⋮  Note';const area=document.createElement('textarea');area.placeholder='Write a thought, question, or connection…';area.value=card.text||'';area.oninput=()=>{card.text=area.value;setState(s)};handle.onclick=()=>{if(!linking)return;if(!linkFirst){linkFirst=card.id;el.classList.add('selected');$('status').textContent='Tap a second note to connect them.'}else if(linkFirst!==card.id){s.links.push([linkFirst,card.id]);setState(s);linkFirst=null;linking=false;$('link-notes').classList.remove('active');$('status').textContent='Notes linked. Tap Link to make another connection.';renderBoard()}};let start=null;handle.onpointerdown=e=>{if(linking)return;start={x:e.clientX,y:e.clientY,left:card.x,top:card.y};handle.setPointerCapture(e.pointerId)};handle.onpointermove=e=>{if(!start)return;card.x=Math.max(0,Math.min(board.clientWidth-160,start.left+e.clientX-start.x));card.y=Math.max(0,Math.min(board.clientHeight-118,start.top+e.clientY-start.y));el.style.left=card.x+'px';el.style.top=card.y+'px';drawLinks(s)};handle.onpointerup=()=>{if(start){setState(s);start=null}};el.append(handle,area);board.append(el)}drawLinks(s);resizeCanvas($('board-ink'),board,s.boardInk)}
function renderAll(){renderDocs();renderPaper();renderBoard()}
$('add-folder').onclick=()=>{const name=prompt('Folder name')?.trim().slice(0,35);if(name&&!folders.includes(name)){folders.push(name);save('rb_folders_v1',folders);renderDocs()}};
$('add-note').onclick=()=>{const s=state();s.cards.push({id:String(Date.now())+Math.random(),x:18+(s.cards.length%3)*27,y:22+(s.cards.length%4)*30,text:''});setState(s);renderBoard()};
$('link-notes').onclick=()=>{linking=!linking;linkFirst=null;$('link-notes').classList.toggle('active',linking);$('status').textContent=linking?'Tap two note handles to link them.':'Notes and ink are saved in this browser.'};
$('doc-pen').onclick=()=>{docPen=!docPen;$('document-ink').classList.toggle('drawing',docPen);$('doc-pen').classList.toggle('active',docPen)};
$('board-pen').onclick=()=>{boardPen=!boardPen;$('board-ink').classList.toggle('drawing',boardPen);$('board-pen').classList.toggle('active',boardPen)};
$('doc-clear').onclick=()=>{const s=state();s.docInk=[];setState(s);drawStrokes($('document-ink'),[])};
$('board-clear').onclick=()=>{const s=state();s.boardInk=[];setState(s);drawStrokes($('board-ink'),[])};
$('export-notes').onclick=()=>{const s=state(),p=byId(current);const names=new Map(s.cards.map((card,index)=>[card.id,`Note ${index+1}`]));const body=s.cards.map((card,index)=>`## Note ${index+1}\n\n${card.text||'(empty)'}`).join('\n\n');const links=s.links.map(([a,b])=>`- ${names.get(a)||a} → ${names.get(b)||b}`).join('\n');const markdown=`# ${p.title}\n\nSource: ${p.url||'unavailable'}\n\n${body}\n\n## Connections\n\n${links||'(none)'}\n`;const url=URL.createObjectURL(new Blob([markdown],{type:'text/markdown'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='researchbridge-notes.md';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),2000);$('status').textContent='Note text and links exported. Pen strokes remain in this browser.'};
ink($('document-ink'),'docInk');ink($('board-ink'),'boardInk');window.addEventListener('resize',()=>{renderPaper();renderBoard()});renderAll();
</script></body></html>'''


def reading_workspace(paper, saved_papers, light=False):
    records=[paper,*[item for item in saved_papers.values() if item['id']!=paper['id']]]
    payload=[dict(id=item['id'],title=item['title'],abstract=item.get('abstract') or '',
        kind=item.get('paper_type'),date=item.get('publication_date'),url=safe_url(item.get('oa_url')) or safe_url(item.get('paper_url')))
        for item in records]
    data=json.dumps(payload,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    st.iframe(HTML.replace('__PAPERS__',data).replace('__THEME__','light' if light else ''),height=610)
